use v5.42;
use strict;
use warnings;
use JSON::PP qw(encode_json decode_json);
use Cwd 'abs_path';
use File::Basename 'dirname';
use Time::HiRes qw(clock_gettime CLOCK_MONOTONIC);
my $worker = abs_path('build/ordinary-matrix-worker.pl');
my $main = '/home/marcus/projects/wump/master';
my @variants = (
	['stock', "$main/build/checkpoint-7a16547/stock/perl/perl-5.42.2/perl"],
	['before', "$main/build/perl/perl-5.42.2/perl"],
	['after', abs_path('build/perl/perl-5.42.2/perl')],
);
my @cases = ([numeric => 2000000], [calls => 1000000], [allocation => 300000],
	[hashes => 500000], [regex => 200000], [strings => 300000], ['encoding-xs' => 100000], [compilation => 10000]);
$| = 1;
for my $fixture (@cases) {
	for my $sample (1..5) {
		for my $offset (0..2) {
			my ($name, $binary) = @{$variants[($offset + $sample - 1) % 3]};
			my $lib = dirname($binary) . '/lib';
			my $start = clock_gettime(CLOCK_MONOTONIC);
			open my $child, '-|', 'timeout', '60s', $binary, "-I$lib", $worker, @$fixture or die $!;
			my $text = do {local $/; <$child>};
			close $child or die "$name @$fixture failed: $?\n$text";
			my $process = clock_gettime(CLOCK_MONOTONIC) - $start;
			my $record = decode_json($text);
			$record->{fixture} eq $fixture->[0] && $record->{iterations} == $fixture->[1]
				&& $record->{verified} && $record->{wall_seconds} > 0 or die 'invalid result';
			print encode_json({%$record, variant => $name, sample => $sample, private_perl => $binary,
				process_seconds => $process}), "\n";
		}
	}
}

ordinary_matrix.worker_source:
use v5.42;
use strict;
use warnings;
use utf8;
use Time::HiRes qw(clock_gettime CLOCK_MONOTONIC);
use JSON::PP 'encode_json';
use Encode qw(encode decode);
my ($case, $n) = @ARGV;
@ARGV == 2 && $n =~ /\A[1-9][0-9]*\z/ or die 'invalid workload';
sub step ($value) { $value + 1 }
my $start = clock_gettime(CLOCK_MONOTONIC);
my ($sum, $expected) = (0, 0);
if ($case eq 'numeric') {
	for my $i (1..$n) { $sum += $i % 97 }
	my $tail = $n % 97;
	$expected = int($n / 97) * 4656 + $tail * ($tail + 1) / 2;
} elsif ($case eq 'calls') {
	for my $i (1..$n) { $sum += step($i) }
	$expected = $n * ($n + 3) / 2;
} elsif ($case eq 'allocation') {
	for my $i (1..$n) {
		my $value = [$i, {value => $i + 1}];
		$sum += $value->[0] + $value->[1]{value};
	}
	$expected = $n * ($n + 2);
} elsif ($case eq 'hashes') {
	my %counts;
	for my $i (1..$n) { ++$counts{$i % 64} }
	$sum += $_ for values %counts;
	my $wall = clock_gettime(CLOCK_MONOTONIC) - $start;
	for my $key (0..63) {
		my $count = int($n / 64) + ($key && $key <= $n % 64 ? 1 : 0);
		($counts{$key} // 0) == $count or die 'wrong hash count';
	}
	$sum == $n or die 'wrong hash sum';
	print encode_json({fixture => $case, iterations => 0+$n, wall_seconds => $wall, verified => JSON::PP::true}), "\n";
	exit;
} elsif ($case eq 'regex') {
	my $text = 'α12 β34 γ56';
	for (1..$n) { $sum += $1 while $text =~ /([0-9]+)/g }
	$expected = 102 * $n;
} elsif ($case eq 'strings') {
	for (1..$n) {
		my $text = uc join '-', reverse split /:/, 'alpha:beta:gamma';
		$text eq 'GAMMA-BETA-ALPHA' or die 'wrong transformed string';
		$sum += length $text;
	}
	$expected = 16 * $n;
} elsif ($case eq 'encoding-xs') {
	my $text = 'aé水';
	for (1..$n) {
		my $bytes = encode('UTF-8', $text);
		decode('UTF-8', $bytes) eq $text or die 'wrong encoding round trip';
		$sum += length $bytes;
	}
	$expected = 6 * $n;
} elsif ($case eq 'compilation') {
	for my $i (1..$n) {
		my $code = eval 'sub ($value) { $value + 1 }';
		$code or die $@;
		$sum += $code->($i);
	}
	$expected = $n * ($n + 3) / 2;
} else { die 'unknown workload' }
my $wall = clock_gettime(CLOCK_MONOTONIC) - $start;
$sum == $expected or die "$case: $sum != $expected";
print encode_json({fixture => $case, iterations => 0+$n, wall_seconds => $wall, verified => JSON::PP::true}), "\n";

ordinary_xs_case.capture_after_source:
use v5.42;
use strict;
use warnings;
use JSON::PP 'encode_json';
use Time::HiRes qw(clock_gettime CLOCK_MONOTONIC);
use File::Basename 'dirname';
use Cwd 'getcwd';
my $task_root = getcwd();
my $main = '/home/marcus/projects/wump/master';
my $stock = "$main/build/checkpoint-7a16547/stock/perl/perl-5.42.2/perl";
local $ENV{PERL5LIB}; delete $ENV{PERL5LIB};
local $ENV{PERL5OPT}; delete $ENV{PERL5OPT};
local $ENV{PERL_CORE} = 1;
$| = 1;
for my $variant (
	["stock", $stock, 3, 120],
	["after", "$task_root/build/perl/perl-5.42.2/perl", 3, 120],
) {
	my ($name, $binary, $runs, $limit) = @$variant;
	for my $sample (1..$runs) {
		chdir dirname($binary) . '/ext/XS-APItest' or die $!;
		open my $log, '>', "$task_root/build/handy-$name-$sample.tap" or die $!;
		my $started = clock_gettime(CLOCK_MONOTONIC);
		open my $child, '-|', 'timeout', "${limit}s", $binary, '-I../../lib', '-I../..',
			'-MTestInit=U2T', 't/handy00.t' or die $!;
		my ($checks, $plan, $failures) = (0, 0, 0);
		while (my $line = <$child>) {
			print {$log} $line or die $!;
			$checks++ if $line =~ /^ok \d+/;
			$plan = $1 if $line =~ /^1\.\.(\d+)/;
			$failures++ if $line =~ /^(?:not ok|Bail out!)/;
		}
		close $child;
		my $status = $?;
		my $wall = clock_gettime(CLOCK_MONOTONIC) - $started;
		close $log or die $!;
		die "$name failed: $status" unless $status == 0 || ($name eq 'before' && $status == 124 << 8);
		die "$name did not verify all macro checks" if !$status && ($checks != 172283 || $plan != $checks || $failures);
		print encode_json({fixture => 'upstream-xs-handy00-v5.42.2', variant => $name,
			sample => $sample, process_seconds => $wall, wait_status => $status,
			completed => $status ? JSON::PP::false : JSON::PP::true,
			verified_checks => $status ? 0 : $checks, observed_checks => $checks,
			private_perl => $binary, timeout_seconds => $limit}), "\n";
	}
}
chdir $task_root or die $!;

